                                                                                                                                                                                                           
  CREATE TABLE "FMP_USER"                                                                                                                                                                        
   (	"USER_ID" NUMBER(20,0) GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"USER_NAME" VARCHAR2(32),                                                                                                                                                                                 
	"JOB_NUMBER" VARCHAR2(32),                                                                                                                                                                                
	"PASSWORD" VARCHAR2(64),                                                                                                                                                                                  
	"MOBILE" NUMBER(20,0),                                                                                                                                                                                    
	"EXT_USER_ID" VARCHAR2(100),                                                                                                                                                                              
	"EMAIL" VARCHAR2(32),                                                                                                                                                                                     
	"UNION_ID" VARCHAR2(255),                                                                                                                                                                                 
	"IS_ENABLE" NUMBER(1,0) DEFAULT 1,                                                                                                                                                                        
	"IS_LEAVE" NUMBER(20,0),                                                                                                                                                                                  
	"USER_TYPE" VARCHAR2(32),                                                                                                                                                                                 
	"TENANT_ID" NUMBER(20,0),                                                                                                                                                                                 
	"REMARK" VARCHAR2(500),                                                                                                                                                                                   
	"CREATED_BY" NUMBER(32,0),                                                                                                                                                                                
	"CREATION_DATE" DATE DEFAULT sysdate,                                                                                                                                                                     
	"UPDATED_BY" NUMBER(20,0),                                                                                                                                                                                
	"UPDATE_DATE" DATE DEFAULT sysdate,                                                                                                                                                                       
	"LAST_LOGIN_TIME" DATE,                                                                                                                                                                                   
	"LAST_SYSTEM_ID" NUMBER(20,0),                                                                                                                                                                            
	"DEL_FLAG" NUMBER(1,0) DEFAULT 0,                                                                                                                                                                         
	 PRIMARY KEY ("USER_ID")                                                                                                                                                                                  
  USING INDEX  ENABLE                                                                                                                                                                                      
   ) ;                                                                                                                                                                                                     


